# Generated by build.py from recipe.yml for recipe smtp-test-a-password-reset-mail. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/index.txt'), "Example app`n")
[IO.File]::WriteAllText((Join-Path $PWD 'no-link.eml'), "From: app@example.com`nTo: carol@example.com`nSubject: Reset your password`n`nOpen this link to choose a new password:`n`n")
[IO.File]::WriteAllText((Join-Path $PWD 'reset-app.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for the app: makes a reset token, publishes the reset page under site/reset/, and`n# mails the recipient a link to it. A fourth argument puts another token in the link, as a bug would.`n# Usage: sh reset-app.sh <smtp port> <http port> <recipient> [<token for the link>]`ntoken=`$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')`nmkdir -p site/reset`nprintf 'Choose a new password for %s.\n' `"`$3`" > `"site/reset/`$token`"`nprintf 'From: app@example.com\nTo: %s\nSubject: Reset your password\n\nOpen this link to choose a new password:\nhttp://127.0.0.1:%s/reset/%s\n' \`n  `"`$3`" `"`$2`" `"`${4:-`$token}`" |`n  curl -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt `"`$3`" \`n    -T - `"smtp://127.0.0.1:`$1/example.com`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check-reset-link.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Reads the reset mail (the INBOX's first message) over IMAP, finds the link in it and fetches it.`n# Usage: sh check-reset-link.sh <user:password> <imap port>`nbody=`$(curl -sS -u `"`$1`" `"imap://127.0.0.1:`$2/INBOX;UID=1;SECTION=TEXT`") || exit `$?`nlink=`$(printf '%s\n' `"`$body`" | tr -d '\r' | sed -n 's|^.*\(http://[^ ]*/reset/[^ ]*\).*`$|\1|p' | head -n 1)`nif [ -z `"`$link`" ]; then`n  echo `"FAIL: no reset link in the mail`"`n  exit 1`nfi`necho `"link: `$link`"`ncurl -sS -f `"`$link`"`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'carol@example.com:carolpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'http://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh reset-app.sh 8080 8082 ann@example.com && sh check-reset-link.sh ann@example.com:annpass 8081 } finally { Stop-Process $server0 }
